-- OmniJarvis D1 migration 0018 — skills library catalog (GAP-FILL).
-- D1: omnijarvis-db (37a7ff24-9fd2-40f9-b122-82cdaea7e79d).
-- New: skill_catalog (server-authored starter skills, seeded below) +
-- skill_catalog_installs (per-tenant installs, enforces the Free=1 cap).
-- Catalog skills are NOT user submissions: they never enter
-- global_skills / quarantine. Manifests are the same v1 JSON the app
-- already parses from /api/skills/sync (name/version/trigger/steps +
-- Anthropic normal form + args schema + gate level).
-- Source of truth: src/skills-catalog.ts STARTER_SKILLS — the INSERTs
-- below are generated from it (tests/skills-catalog.test.ts asserts
-- the SQL rows match STARTER_SKILLS exactly). Do NOT hand-edit rows.
-- Non-destructive: CREATE TABLE IF NOT EXISTS + INSERT ... ON CONFLICT
-- DO NOTHING only.
CREATE TABLE IF NOT EXISTS skill_catalog (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  manifest TEXT NOT NULL,
  category TEXT NOT NULL,
  tier TEXT NOT NULL CHECK (tier IN ('free', 'pro', 'business')),
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_skill_catalog_tier ON skill_catalog(tier, created_at);
CREATE TABLE IF NOT EXISTS skill_catalog_installs (
  tenant_id TEXT NOT NULL,
  skill_id TEXT NOT NULL,
  installed_at INTEGER NOT NULL,
  PRIMARY KEY (tenant_id, skill_id)
);
CREATE INDEX IF NOT EXISTS idx_skill_catalog_installs_tenant ON skill_catalog_installs(tenant_id, installed_at);
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-email-management', 'email-management', 'Read, search, draft and send email on the connected Gmail account. Use when the user asks about an email, wants a reply drafted, or wants mail sent.', '{"format":"anthropic","name":"email-management","description":"Read, search, draft and send email on the connected Gmail account. Use when the user asks about an email, wants a reply drafted, or wants mail sent.","version":"1.0.0","trigger":"email","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["gmail-messages","gmail-send"],"instructions":"Email management for the user''s connected Gmail account (hub routes /api/google/gmail/messages and /api/google/gmail/send).\n\nWhen to use: finding an email, drafting a reply, sending mail the user asked for, summarising a thread.\n\nSteps:\n1. Read the request literally. A search needs only a query. A draft needs recipient, subject and the points to cover. A send needs all three plus the user''s explicit yes on the exact text.\n2. Search first with the messages route. Read the newest matching messages and quote the sender, date and subject back to the user before acting on any of them.\n3. Drafts are shown to the user first and sent only after they approve the exact text. Never send a draft the user has not seen.\n4. Summaries keep numbers, dates, links and action items verbatim and say which message each fact came from.\n\nLimits: Gmail only, the connected account only. No other mailbox. Attachments are listed, never silently downloaded. If Gmail is not connected, say so and stop.","args":{"type":"object","properties":{"action":{"type":"string","enum":["search","draft","send","summarize"]},"query":{"type":"string","description":"Search text for finding mail"},"to":{"type":"string","description":"Recipient email address"},"subject":{"type":"string"},"body":{"type":"string","description":"Draft or message text"},"max_results":{"type":"integer","default":10}},"required":["action"]},"gate":"approval","origin":"catalog"}', 'communication', 'free', 1795478400000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-scheduling', 'scheduling', 'Check the calendar and create or cancel events on the connected Google Calendar. Use when the user asks what is free, or wants an event made.', '{"format":"anthropic","name":"scheduling","description":"Check the calendar and create or cancel events on the connected Google Calendar. Use when the user asks what is free, or wants an event made.","version":"1.0.0","trigger":"schedule","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["calendar-events"],"instructions":"Calendar scheduling through the hub routes /api/google/calendar/events (GET to list, POST to create).\n\nWhen to use: checking what is free, creating an event, cancelling one the user named.\n\nSteps:\n1. Ask for what is missing before creating anything: title, start, end and who is invited. Never guess a time.\n2. List events for the requested day first so a new event never double-books silently. If it overlaps, say so and ask.\n3. Create the event, then read it back and confirm the title, time and attendees to the user.\n4. Cancel only the exact event the user named. Read the event back before cancelling and confirm after.\n\nLimits: Google Calendar only, the connected account only. Times are the user''s local timezone unless they say otherwise. No recurring-series edits in v1, one event at a time.","args":{"type":"object","properties":{"action":{"type":"string","enum":["list","create","cancel"]},"title":{"type":"string"},"start":{"type":"string","description":"Start time, ISO 8601"},"end":{"type":"string","description":"End time, ISO 8601"},"attendees":{"type":"array","items":{"type":"string"}},"description":{"type":"string"}},"required":["action"]},"gate":"confirm","origin":"catalog"}', 'productivity', 'free', 1795478401000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-web-research', 'web-research', 'Answer questions that need current facts from the web, with a source and a date for every claim. Use when the user asks something that needs live information.', '{"format":"anthropic","name":"web-research","description":"Answer questions that need current facts from the web, with a source and a date for every claim. Use when the user asks something that needs live information.","version":"1.0.0","trigger":"research","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["web-search","webview-browser"],"instructions":"Web research using the hub LLM router (BYOK Gemini or Groq) plus the in-app WebView browser for live pages.\n\nWhen to use: any question that needs current facts, comparisons, or sources from the web.\n\nSteps:\n1. Break the question into the smallest checkable claims.\n2. Search each claim and open the source page. Prefer the primary source over an aggregator that republishes it.\n3. Report each fact with its source and date. If two sources disagree, show both and say which one is primary.\n4. A fact with no source is labelled as unverified, never stated as true.\n\nLimits: no paywalled source is ever claimed as read. Dates on republished listings are not trusted on their own, read the internal dates on the page.","args":{"type":"object","properties":{"query":{"type":"string"},"depth":{"type":"string","enum":["quick","deep"],"default":"quick"},"max_sources":{"type":"integer","default":5}},"required":["query"]},"gate":"none","origin":"catalog"}', 'research', 'free', 1795478402000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-documents', 'documents', 'Write documents, pull structured fields out of them, and make shareable certificate links. Use when the user wants a report, a note, or fields extracted from a file.', '{"format":"anthropic","name":"documents","description":"Write documents, pull structured fields out of them, and make shareable certificate links. Use when the user wants a report, a note, or fields extracted from a file.","version":"1.0.0","trigger":"document","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["docs-ingest","docs-extract","docs-certificate"],"instructions":"Documents through the hub docs routes: /api/docs/ingest to store text, /api/docs/extract for structured fields, /api/docs/certificate for a shareable certificate link.\n\nWhen to use: writing a report or note, pulling fields out of a document, making a document shareable.\n\nSteps:\n1. Ask what the document is for and who will read it before writing. Keep the user''s words where they gave them.\n2. Draft in full, then show the draft. Edit only after the user approves the shape.\n3. Extraction returns the fields the user asked for with the source page or line for each one. A field that is not in the document is reported as missing, never guessed.\n4. A certificate link is created only when the user asks to share. Say who can open it before creating it.\n\nLimits: text documents only in v1. Spreadsheets and slides are out of scope and must be refused plainly.","args":{"type":"object","properties":{"action":{"type":"string","enum":["create","read","extract","certificate"]},"title":{"type":"string"},"text":{"type":"string","description":"Document text to store or draft"},"fields":{"type":"array","items":{"type":"string"},"description":"Fields to extract"}},"required":["action"]},"gate":"confirm","origin":"catalog"}', 'productivity', 'pro', 1795478403000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-place-discovery', 'place-discovery', 'Find and compare places to go, restaurants, cafes, shops, parks and services, with a Maps link each. Use when the user asks where to go or what is nearby.', '{"format":"anthropic","name":"place-discovery","description":"Find and compare places to go, restaurants, cafes, shops, parks and services, with a Maps link each. Use when the user asks where to go or what is nearby.","version":"1.0.0","trigger":"place","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["web-search","maps-link"],"instructions":"Finding places (restaurants, cafes, shops, parks, attractions, services) by web research plus a Maps link.\n\nWhen to use: the user asks where to go, what is nearby, or which place is best for a need.\n\nSteps:\n1. Ask for the area and the need (cuisine, budget, timing) when the user did not give them.\n2. Search the web for candidates and verify each one on its own site or Maps listing: address, hours and phone.\n3. Compare at most five places on the same points: distance, hours, price signal and what people say about it.\n4. Give the shortlist with a Maps link per place. Hours and prices are stated as last-checked, with the date.\n\nLimits: Jarvis has no live Places API in v1, so hours and prices are verified from the web, never from memory. A place that cannot be verified is marked unverified.","args":{"type":"object","properties":{"query":{"type":"string"},"location":{"type":"string","description":"Area or city"},"kind":{"type":"string","enum":["restaurant","cafe","shop","park","attraction","service"]}},"required":["query"]},"gate":"none","origin":"catalog"}', 'research', 'pro', 1795478404000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-trip-planning', 'trip-planning', 'Plan a trip, compare transport and stays by total price, and lay out the itinerary. Use when the user wants a trip planned. It never books or pays.', '{"format":"anthropic","name":"trip-planning","description":"Plan a trip, compare transport and stays by total price, and lay out the itinerary. Use when the user wants a trip planned. It never books or pays.","version":"1.0.0","trigger":"trip","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["web-search","calendar-events"],"instructions":"Trip planning by web research plus the calendar. It plans and compares. It never books or pays anything on its own.\n\nWhen to use: the user wants a trip planned, a route compared, or a stay shortlisted.\n\nSteps:\n1. Collect destination, dates, travellers, budget and interests. Plan nothing until the dates and budget are known.\n2. Research transport and stays from live sources and compare like for like: total price, time, location and terms.\n3. Present one itinerary with options per leg and per night, each with its price and its source.\n4. Booking is a link the user opens. Payment is always the user''s own explicit step, never the agent''s.\n\nLimits: no auto-booking, no payment, no saved cards. Prices are last-checked with the date, never promised.","args":{"type":"object","properties":{"destination":{"type":"string"},"start_date":{"type":"string","description":"Trip start, YYYY-MM-DD"},"end_date":{"type":"string","description":"Trip end, YYYY-MM-DD"},"budget":{"type":"string"},"travelers":{"type":"integer","default":1},"interests":{"type":"array","items":{"type":"string"}}},"required":["destination"]},"gate":"approval","origin":"catalog"}', 'travel', 'pro', 1795478405000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-shopping', 'shopping', 'Find a product and compare merchant offers by delivered total, then hand over the checkout link. Use when the user wants to buy or price-check something. It never buys.', '{"format":"anthropic","name":"shopping","description":"Find a product and compare merchant offers by delivered total, then hand over the checkout link. Use when the user wants to buy or price-check something. It never buys.","version":"1.0.0","trigger":"shop","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["web-search"],"instructions":"Shopping research: find a product, compare offers by delivered total, and hand the user the checkout link. It never buys anything.\n\nWhen to use: the user wants to buy something, compare prices, or check whether an offer is genuine.\n\nSteps:\n1. Pin down the exact product: model, variant, size and colour. A vague name gets a clarifying question first.\n2. Search several merchants and compare the delivered total: price plus shipping, taxes and fees. The cheapest headline price is not the answer.\n3. Check the seller and the return terms before recommending. A deal with no return path is flagged, not recommended.\n4. Hand over the checkout link for the chosen offer. The user pays. The agent never enters a card or completes a purchase.\n\nLimits: no purchase, no payment, no card handling. Prices are last-checked with the date. Used-marketplace listings are compared on condition and seller history, not price alone.","args":{"type":"object","properties":{"query":{"type":"string","description":"Exact product, model and variant"},"max_price":{"type":"number"},"category":{"type":"string"}},"required":["query"]},"gate":"approval","origin":"catalog"}', 'commerce', 'pro', 1795478406000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-messaging', 'messaging', 'Draft and send messages in the Jarvis in-app chat. Use when the user wants a message written or sent. WhatsApp and SMS are not available in v1.', '{"format":"anthropic","name":"messaging","description":"Draft and send messages in the Jarvis in-app chat. Use when the user wants a message written or sent. WhatsApp and SMS are not available in v1.","version":"1.0.0","trigger":"message","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["in-app-chat","fcm-push"],"instructions":"Messaging in Jarvis means the in-app chat and FCM push. There is no WhatsApp or SMS sending in v1.\n\nWhen to use: drafting a message the user wants to send, or sending an in-app message or reminder to someone the user names.\n\nSteps:\n1. Draft the exact text first and show it to the user. Nothing is sent unseen.\n2. Send only after the user''s yes, only to the person they named, only the text they approved.\n3. After sending, report what was sent, to whom, and when.\n4. A request to message someone on WhatsApp or SMS is refused plainly with the reason: Jarvis has no WhatsApp number or SMS sender in v1.\n\nLimits: in-app chat and FCM only. No message is ever sent without the approved text. Group messages are one recipient list the user confirms.","args":{"type":"object","properties":{"action":{"type":"string","enum":["draft","send"]},"recipient":{"type":"string"},"text":{"type":"string"}},"required":["action","text"]},"gate":"approval","origin":"catalog"}', 'communication', 'pro', 1795478407000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-meeting-follow-up', 'meeting-follow-up', 'Turn meeting notes or a transcript into decisions, owners, action items and a sendable recap. Use after a meeting when the user shares notes or a transcript.', '{"format":"anthropic","name":"meeting-follow-up","description":"Turn meeting notes or a transcript into decisions, owners, action items and a sendable recap. Use after a meeting when the user shares notes or a transcript.","version":"1.0.0","trigger":"meeting","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["gmail-send","drive-upload"],"instructions":"Meeting follow-up from a transcript or notes: decisions, owners, action items and a recap the user can send.\n\nWhen to use: after a meeting, when the user shares notes or a transcript and wants the follow-up written.\n\nSteps:\n1. Read the transcript or notes fully. A decision is recorded only when the text states it. A guess is labelled as a guess.\n2. List every action item with its owner and its due date. An item with no owner is flagged, not assigned.\n3. Write the recap: decisions first, then action items, then open questions. Keep it short enough to send.\n4. Sending the recap (email or in-app message) needs the user''s yes on the exact text and the exact recipients.\n\nLimits: no transcript, no follow-up. The agent never invents attendees, decisions or dates. A recording is transcribed only from the audio the user provided.","args":{"type":"object","properties":{"transcript":{"type":"string","description":"Meeting notes or transcript text"},"attendees":{"type":"array","items":{"type":"string"}},"meeting_title":{"type":"string"},"date":{"type":"string","description":"Meeting date, YYYY-MM-DD"}},"required":["transcript"]},"gate":"approval","origin":"catalog"}', 'communication', 'pro', 1795478408000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-knowledge-organization', 'knowledge-organization', 'Save notes and documents to Drive, find them again, and keep the user''s own folders and tags. Use when the user wants something saved, found, or filed.', '{"format":"anthropic","name":"knowledge-organization","description":"Save notes and documents to Drive, find them again, and keep the user''s own folders and tags. Use when the user wants something saved, found, or filed.","version":"1.0.0","trigger":"organize","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["drive-files","drive-upload"],"instructions":"Knowledge organization: save notes and documents to Drive, find them again, and keep the structure the user already uses.\n\nWhen to use: the user wants something saved for later, found again, or filed under a topic.\n\nSteps:\n1. Save with a clear title, the date and the tags the user gave. A note with no title gets one from its first line.\n2. Finding starts with the user''s own words. Search Drive and the saved notes before searching the web.\n3. When filing, use the folders and tags that already exist. A new folder is created only when the user asks for it.\n4. Report where it was saved or found, with the exact title, so the user can open it.\n\nLimits: Drive only, the connected account only. Nothing is deleted or moved without the user naming it. Private notes are never shared.","args":{"type":"object","properties":{"action":{"type":"string","enum":["save","find","organize"]},"title":{"type":"string"},"content":{"type":"string"},"tags":{"type":"array","items":{"type":"string"}}},"required":["action"]},"gate":"confirm","origin":"catalog"}', 'productivity', 'pro', 1795478409000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-live-page-checks', 'live-page-checks', 'Read a live product page and report its current price, stock or availability with the check time. Use when the user asks what something costs or whether it is in stock right now.', '{"format":"anthropic","name":"live-page-checks","description":"Read a live product page and report its current price, stock or availability with the check time. Use when the user asks what something costs or whether it is in stock right now.","version":"1.0.0","trigger":"check page","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["webview-browser"],"instructions":"Live page checks: read a current product page through the WebView browser and report price, stock or availability as of now.\n\nWhen to use: the user asks whether something is in stock, what it costs right now, or whether a page changed.\n\nSteps:\n1. Open the exact URL the user gave. A search result is not a page check.\n2. Read the price, stock state and any delivery note directly from the page. Quote the text you read.\n3. Say when you checked it. A check from an hour ago is stale and is labelled as such.\n4. If the page will not load, say so plainly and stop. Never report a price from memory or from another site.\n\nLimits: one URL per check. Login-walled pages are reported as unreadable, never bypassed. No purchase follows a check without a separate user step.","args":{"type":"object","properties":{"url":{"type":"string","description":"Exact product page URL"},"check":{"type":"string","enum":["price","stock","availability"]},"target_price":{"type":"number","description":"Alert when the price drops to this"}},"required":["url","check"]},"gate":"none","origin":"catalog"}', 'research', 'pro', 1795478410000) ON CONFLICT(id) DO NOTHING;
INSERT INTO skill_catalog (id, name, description, manifest, category, tier, created_at) VALUES ('cat-transcription', 'transcription', 'Turn audio the user provides into text with speaker labels and a summary, using on-device speech recognition. Use when the user shares a recording and wants the words as text.', '{"format":"anthropic","name":"transcription","description":"Turn audio the user provides into text with speaker labels and a summary, using on-device speech recognition. Use when the user shares a recording and wants the words as text.","version":"1.0.0","trigger":"transcribe","steps":[{"action":"follow-skill-instructions"}],"allowed_tools":["speech-to-text"],"instructions":"Transcription of audio the user provides, using the phone''s on-device speech recognition, returned as text with speaker labels and a short summary.\n\nWhen to use: the user shares a recording or voice note and wants the words as text.\n\nSteps:\n1. Take the audio the user provided. No audio, no transcript.\n2. Transcribe in bounded chunks and keep going where the last chunk ended. A chunk that fails is retried once, then reported as untranscribed.\n3. Mark uncertain words as uncertain. Mark speaker changes where they are clear. Never smooth a sentence into words the speaker did not say.\n4. Return the full text plus a short summary: the points made and any numbers, dates or names spoken.\n\nLimits: on-device speech recognition only in v1. A language the recognizer does not support is refused plainly. No transcript is ever invented for silent or unclear audio.","args":{"type":"object","properties":{"audio_ref":{"type":"string","description":"Reference to the user-provided audio"},"language":{"type":"string","default":"hi-IN"},"speakers":{"type":"boolean","default":true}},"required":["audio_ref"]},"gate":"none","origin":"catalog"}', 'productivity', 'pro', 1795478411000) ON CONFLICT(id) DO NOTHING;
INSERT OR IGNORE INTO d1_migrations (name, applied_at) VALUES ('0018_skills_catalog.sql', CAST(strftime('%s','now') AS INTEGER)*1000);
